function CC_onCfgChange(zone){
  CC_updateCfgDisplays();
  CC_recalc();
}
function CC_updateCfgDisplays(){
  // Grenier
  var gr=CC_pf(CC_gid('CC_cfgGrenierR')?CC_gid('CC_cfgGrenierR').value:'60')||60;
  var gd=CC_pf(CC_gid('CC_cfgGrenierDens')?CC_gid('CC_cfgGrenierDens').value:'1.52')||1.52;
  var gEp=CC_interpR2Ep('grenier',gr);
  var cfgGrEp=CC_gid('CC_cfgGrenierEp');
  if(cfgGrEp)cfgGrEp.textContent=CC_fmt(gEp,1)+' po';
  // Plafonds
  var pd=CC_pf(CC_gid('CC_cfgPlafondsDens')?CC_gid('CC_cfgPlafondsDens').value:'2.0')||2.0;
  var pHt=CC_pf(CC_gid('CC_cfgPlafondsHt')?CC_gid('CC_cfgPlafondsHt').value:'11.875')||11.875;
  var pR=CC_interpEp2R('plafonds',pHt);
  var cfgPR=CC_gid('CC_cfgPlafondsR');
  if(cfgPR)cfgPR.textContent='R-'+Math.round(pR);
  // Murs
  var mEp=CC_readCfgMursEp();
  var mR=CC_rForMurEpDens(mEp,CC_pf(CC_gid('CC_cfgMursDens')?CC_gid('CC_cfgMursDens').value:'4.0')||4.0);
  var cfgMR=CC_gid('CC_cfgMursR');
  if(cfgMR)cfgMR.textContent='R-'+Math.round(mR);
}
function CC_readCfgMursEp(){
  if(CC_unitSystem==='mm'){
    var mm=CC_pf(CC_gid('CC_cfgMurs_mm')?CC_gid('CC_cfgMurs_mm').value:'0');
    return CC_mmToIn(mm);
  }
  return CC_readImpPi('CC_cfgMurs_pi','CC_cfgMurs_po');
}
function CC_applyCfgToAll(zone){
  if(zone==='grenier'){
    var r=CC_pf(CC_gid('CC_cfgGrenierR')?CC_gid('CC_cfgGrenierR').value:60)||60;
    var d=CC_pf(CC_gid('CC_cfgGrenierDens')?CC_gid('CC_cfgGrenierDens').value:1.52)||1.52;
    CC_rows.grenier.forEach(function(row){row.rVal=r;row.dens=d;});
    CC_renderTable('grenier');
  } else if(zone==='plafonds'){
    var ht=CC_pf(CC_gid('CC_cfgPlafondsHt')?CC_gid('CC_cfgPlafondsHt').value:11.875)||11.875;
    var d=CC_pf(CC_gid('CC_cfgPlafondsDens')?CC_gid('CC_cfgPlafondsDens').value:2.0)||2.0;
    CC_rows.plafonds.forEach(function(row){row.ht=ht;row.dens=d;});
    CC_renderTable('plafonds');
  } else if(zone==='murs'){
    var ep=CC_readCfgMursEp();
    var d=CC_pf(CC_gid('CC_cfgMursDens')?CC_gid('CC_cfgMursDens').value:4.0)||4.0;
    CC_rows.murs.forEach(function(row){row.ep=ep;row.dens=d;});
    CC_rows.pig.forEach(function(row){row.ep=ep;row.dens=d;});
    CC_renderTable('murs');CC_renderTable('pig');
  }
  CC_recalc();
}

