function CC_toggleCol(zone,col,show){
  var tbl=CC_gid('CC_tbl_'+zone);
  if(!tbl)return;
  if(show) tbl.classList.remove('gp-hide-'+col);
  else tbl.classList.add('gp-hide-'+col);
}

// ─────────────────────────────────────────────────────────
//  BUFFER
// ─────────────────────────────────────────────────────────
function CC_getBuf(){
  var v=CC_pf(CC_gid('CC_bufInput')?CC_gid('CC_bufInput').value:'5');
  return isNaN(v)?5:Math.max(0,Math.min(30,v));
}
function CC_syncBuffer(src){
  var v;
  if(src==='slider') v=CC_pf(CC_gid('CC_bufSlider').value);
  else if(src==='summary-slider') v=CC_pf(CC_gid('CC_sBufSlider').value);
  else if(src==='input') v=CC_pf(CC_gid('CC_bufInput').value);
  else v=CC_pf(CC_gid('CC_sBufInput').value);
  v=Math.max(0,Math.min(30,isNaN(v)?5:v));
  ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=v+'%';
  CC_recalc();
}
function CC_clampBuffer(){
  var v=CC_getBuf();
  ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=v+'%';
}

// ─────────────────────────────────────────────────────────
//  CALCUL PRINCIPAL
// ─────────────────────────────────────────────────────────
function CC_recalc(){
  var buf=CC_getBuf()/100;
  var totGrenier=0,totPlafonds=0,totMurs=0,totPig=0,totOuv=0;
  var totSurfGrenier=0,totSurfPlafonds=0,totSurfMurs=0;

  // GRENIER
  var grenierR=CC_pf(CC_gid('CC_grenierR')?CC_gid('CC_grenierR').value:60)||60;
  var grenierDens=CC_pf(CC_gid('CC_grenierDens')?CC_gid('CC_grenierDens').value:1.52)||1.52;
  var grenierEp=CC_interpR2Ep('grenier',grenierR);
  var grenierEpEl=CC_gid('CC_grenierEp');
  if(grenierEpEl&&document.activeElement!==grenierEpEl)grenierEpEl.value=CC_fmt(grenierEp,2);

  CC_rows.grenier.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    // Surface: si saisie directe, utiliser; sinon calculer à partir de L×W
    var surf=CC_pf(row.surf);
    if(!surf){
      var l_po,w_po;
      if(CC_unitSystem==='mm'){
        l_po=CC_mmToIn(CC_pf(row.l_mm));
        w_po=CC_mmToIn(CC_pf(row.w_mm));
      } else {
        l_po=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);
        w_po=(CC_pf(row.w_pi)||0)*12+(CC_pf(row.w_po)||0);
      }
      surf=CC_surfFromDims(l_po,w_po);
    }
    row._surf=surf;
    var rRow=row.rVal||grenierR;
    var dRow=row.dens||grenierDens;
    var epRow=CC_interpR2Ep('grenier',rRow);
    var sacs=CC_sacsForSurf('grenier',surf,epRow,dRow)*qty;
    row._sacs=sacs/qty;
    // Mise à jour DOM
    var surfEl=CC_gid('CC_surf_'+row.id);
    if(surfEl&&!CC_pf(row.surf))surfEl.value=surf?CC_fmt(surf,2):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.value='R-'+Math.round(rRow);
    var epEl=CC_gid('CC_ep_'+row.id);if(epEl)epEl.value=CC_fmt(epRow,1)+' po';
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totGrenier+=sacs;
    totSurfGrenier+=surf*qty;
  });

  // PLAFONDS
  var plafondHt=CC_pf(CC_gid('CC_plafondHt')?CC_gid('CC_plafondHt').value:11.875)||11.875;
  var plafondDens=CC_pf(CC_gid('CC_plafondDens')?CC_gid('CC_plafondDens').value:2.0)||2.0;
  var plafondR=CC_interpEp2R('plafonds',plafondHt);
  var plafREl=CC_gid('CC_plafondR');if(plafREl)plafREl.value='R-'+Math.round(plafondR);

  CC_rows.plafonds.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var surf=CC_pf(row.surf);
    if(!surf){
      var l_po,w_po;
      if(CC_unitSystem==='mm'){l_po=CC_mmToIn(CC_pf(row.l_mm));w_po=CC_mmToIn(CC_pf(row.w_mm));}
      else{l_po=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);w_po=(CC_pf(row.w_pi)||0)*12+(CC_pf(row.w_po)||0);}
      surf=CC_surfFromDims(l_po,w_po);
    }
    row._surf=surf;
    var htRow=row.ht||plafondHt;
    var dRow=row.dens||plafondDens;
    var rRow=CC_interpEp2R('plafonds',htRow);
    var sacs=CC_sacsForSurf('plafonds',surf,htRow,dRow)*qty;
    row._sacs=sacs/qty;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl&&!CC_pf(row.surf))surfEl.value=surf?CC_fmt(surf,2):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.value='R-'+Math.round(rRow);
    var epEl=CC_gid('CC_ep_'+row.id);if(epEl)epEl.value=CC_fmt(htRow,2)+' po';
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totPlafonds+=sacs;
    totSurfPlafonds+=surf*qty;
  });

  // MURS
  CC_rows.murs.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var surf=CC_pf(row.surf);
    if(!surf){
      var l_po,h_po;
      if(CC_unitSystem==='mm'){l_po=CC_mmToIn(CC_pf(row.l_mm));h_po=CC_mmToIn(CC_pf(row.h_mm));}
      else{l_po=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);h_po=(CC_pf(row.h_pi)||0)*12+(CC_pf(row.h_po)||0);}
      surf=CC_surfFromDims(l_po,h_po);
    }
    row._surf=surf;
    var epRow=CC_pf(row.ep)||5.5;
    var dRow=CC_pf(row.dens)||4.0;
    var rRow=CC_rForMurEpDens(epRow,dRow);
    var sacs=CC_sacsForSurf('murs',surf,epRow,dRow)*qty;
    row._sacs=sacs/qty;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl&&!CC_pf(row.surf))surfEl.value=surf?CC_fmt(surf,2):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.textContent='R-'+Math.round(rRow);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totMurs+=sacs;
    totSurfMurs+=surf*qty;
  });

  // PIGNONS
  CC_rows.pig.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var l1,l2=0,p1=CC_pf(row.pente1)||6,p2=CC_pf(row.pente2)||6;
    if(CC_unitSystem==='mm'){l1=CC_mmToIn(CC_pf(row.l1_mm));l2=CC_mmToIn(CC_pf(row.l2_mm));}
    else{l1=(CC_pf(row.l1_pi)||0)*12+(CC_pf(row.l1_po)||0);l2=(CC_pf(row.l2_pi)||0)*12+(CC_pf(row.l2_po)||0);}
    l1/=12;l2/=12; // en pieds
    var surf=0,seg=0;
    if(row.type==='mono'){
      var slope=Math.sqrt(1+Math.pow(p1/12,2));
      surf=0.5*l1*l1*(p1/12);
      seg=l1*slope;
    } else if(row.type==='centre'){
      var slope=Math.sqrt(1+Math.pow(p1/12,2));
      surf=0.5*(l1+l2)*(l1/2*(p1/12));
      seg=(l1/2)*slope*2;
    } else {
      var s1=Math.sqrt(1+Math.pow(p1/12,2)),s2=Math.sqrt(1+Math.pow(p2/12,2));
      var h=l1*(p1/12);
      var base2=l1;
      surf=0.5*base2*h;
      seg=l1*s1;
    }
    row._surf=surf;
    var epRow=CC_pf(row.ep)||5.5;
    var dRow=CC_pf(row.dens)||4.0;
    var sacs=CC_sacsForSurf('murs',surf,epRow,dRow)*qty;
    row._sacs=sacs/qty;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl)surfEl.textContent=CC_fmt(surf,1);
    var segEl=CC_gid('CC_seg_'+row.id);if(segEl)segEl.textContent=CC_fmt(seg*12,1)+' po';
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totPig+=sacs;
    totSurfMurs+=surf*qty;
  });

  // OUVERTURES — retrancher des murs
  CC_rows.ouv.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var jeu=CC_pf(row.jeu)||0.5;
    var l_po,h_po;
    if(CC_unitSystem==='mm'){l_po=CC_mmToIn(CC_pf(row.l_mm));h_po=CC_mmToIn(CC_pf(row.h_mm));}
    else{l_po=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);h_po=(CC_pf(row.h_pi)||0)*12+(CC_pf(row.h_po)||0);}
    var lTot=l_po+2*jeu,hTot=h_po+2*jeu;
    var surf=CC_surfFromDims(lTot,hTot);
    var perim=2*(lTot+hTot)/12;
    row._surf=surf;
    // Sacs à retrancher (en utilisant l'épaisseur moyenne des murs)
    var epMurs=CC_pf(CC_gid('CC_mursEp')?CC_gid('CC_mursEp').value:5.5)||5.5;
    var dMurs=CC_pf(CC_gid('CC_mursDens')?CC_gid('CC_mursDens').value:4.0)||4.0;
    var sacs=CC_sacsForSurf('murs',surf,epMurs,dMurs)*qty;
    row._sacs=sacs/qty;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl)surfEl.textContent=CC_fmt(surf,2);
    var perimEl=CC_gid('CC_perim_'+row.id);if(perimEl)perimEl.textContent=CC_fmt(perim,2);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent='-'+CC_fmtInt(sacs);
    totOuv+=sacs;
  });

  // Sous-totaux
  var stGr=CC_gid('CC_stSurfGrenier');if(stGr)stGr.textContent=CC_fmt(totSurfGrenier,1);
  var stGrS=CC_gid('CC_stSacsGrenier');if(stGrS)stGrS.textContent=CC_fmtInt(totGrenier);
  var stPl=CC_gid('CC_stSurfPlafonds');if(stPl)stPl.textContent=CC_fmt(totSurfPlafonds,1);
  var stPlS=CC_gid('CC_stSacsPlafonds');if(stPlS)stPlS.textContent=CC_fmtInt(totPlafonds);
  var stMu=CC_gid('CC_stSurfMurs');if(stMu)stMu.textContent=CC_fmt(totSurfMurs,1);
  var stMuS=CC_gid('CC_stSacsMurs');if(stMuS)stMuS.textContent=CC_fmtInt(totMurs+totPig);
  var stOvS=CC_gid('CC_stSacsOuv');if(stOvS)stOvS.textContent='-'+CC_fmtInt(totOuv);
  var stPgS=CC_gid('CC_stSacsPig');if(stPgS)stPgS.textContent=CC_fmtInt(totPig);

  var netMursTotal=Math.max(0,totMurs+totPig-totOuv);
  var netTotal=totGrenier+totPlafonds+netMursTotal;
  var bufTotal=Math.ceil(netTotal*(1+buf));
  var palTotal=Math.ceil(bufTotal/42);

  // Section matériaux
  var rGr=CC_gid('CC_resGrenier');if(rGr)rGr.textContent=CC_fmtInt(totGrenier);
  var rGs=CC_gid('CC_resGrenierSurf');if(rGs)rGs.textContent=CC_fmt(totSurfGrenier,1)+' pi\u00b2';
  var rPl=CC_gid('CC_resPlafonds');if(rPl)rPl.textContent=CC_fmtInt(totPlafonds);
  var rPs=CC_gid('CC_resPlafondsSurf');if(rPs)rPs.textContent=CC_fmt(totSurfPlafonds,1)+' pi\u00b2';
  var rMu=CC_gid('CC_resMurs');if(rMu)rMu.textContent=CC_fmtInt(netMursTotal);
  var rMs=CC_gid('CC_resMursSurf');if(rMs)rMs.textContent=CC_fmt(totSurfMurs,1)+' pi\u00b2';
  var rNet=CC_gid('CC_resCellSacNet');if(rNet)rNet.textContent=CC_fmtInt(netTotal);
  var rBuf=CC_gid('CC_resCellSacBuf');if(rBuf)rBuf.textContent=String(bufTotal);
  var rPal=CC_gid('CC_resCellPal');if(rPal)rPal.textContent=String(palTotal);

  // Summary sidebar
  var totSurf=totSurfGrenier+totSurfPlafonds+totSurfMurs;
  var hS=CC_gid('CC_heroSacs');if(hS)hS.textContent=String(bufTotal);
  var hSurf=CC_gid('CC_heroSurf');if(hSurf)hSurf.textContent=CC_fmt(totSurf,1)+' pi\u00b2';
  var hP=CC_gid('CC_heroPal');if(hP)hP.textContent=palTotal+' pal.';
  var sGr=CC_gid('CC_sumGrenier');if(sGr)sGr.textContent=CC_fmtInt(totGrenier);
  var sGrs=CC_gid('CC_sumSubGrenier');if(sGrs)sGrs.textContent=CC_fmt(totSurfGrenier,1)+' pi\u00b2';
  var sPl=CC_gid('CC_sumPlafonds');if(sPl)sPl.textContent=CC_fmtInt(totPlafonds);
  var sPls=CC_gid('CC_sumSubPlafonds');if(sPls)sPls.textContent=CC_fmt(totSurfPlafonds,1)+' pi\u00b2';
  var sMu=CC_gid('CC_sumMurs');if(sMu)sMu.textContent=CC_fmtInt(netMursTotal);
  var sMus=CC_gid('CC_sumSubMurs');if(sMus)sMus.textContent=CC_fmt(totSurfMurs,1)+' pi\u00b2';
  var tN=CC_gid('CC_totSacsNet');if(tN)tN.textContent=CC_fmtInt(netTotal);
  var tP=CC_gid('CC_totPal');if(tP)tP.textContent=String(palTotal);
  var tB=CC_gid('CC_totSacsBuf');if(tB)tB.textContent=String(bufTotal);

  // Éléments Odoo
  var bagN=CC_gid('CC_bags_num');if(bagN)bagN.textContent=CC_fmtInt(netTotal);
  var metaS=CC_gid('CC_meta_surplus');if(metaS)metaS.textContent=String(bufTotal);

  // Récap sections
  CC_updateSectionRecap(totGrenier,totPlafonds,netMursTotal);

  // Sous-totaux sections dans les tables
  if(CC_sections.length>1){
    ['grenier','plafonds','murs'].forEach(function(zone){
      CC_sections.forEach(function(sec){
        var subTr=document.querySelector('#CC_tbody_'+zone+' tr[data-sec-sub="'+sec.id+'"]');
        if(subTr)subTr.innerHTML=CC_makeSecSubTd(zone,sec.id,CC_rows[zone]);
      });
    });
  }
}

function CC_updateSectionRecap(gr,pl,mu){
  var card=CC_gid('CC_sectionRecapCard');
  if(!card)return;
  if(CC_sections.length<2){card.style.display='none';return;}
  card.style.display='';
  var div=CC_gid('CC_sectionRecap');
  if(!div)return;
  var html='<table class="sec-recap-table"><thead><tr><th>Section</th><th>Grenier</th><th>Plafond</th><th>Murs</th><th>Total</th></tr></thead><tbody>';
  var totGr=0,totPl=0,totMu=0;
  CC_sections.forEach(function(sec){
    var sgr=0,spl=0,smu=0;
    ['grenier'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){sgr+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    ['plafonds'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){spl+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    ['murs','pig'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){smu+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    var tot=sgr+spl+smu;
    totGr+=sgr;totPl+=spl;totMu+=smu;
    html+='<tr><td class="sec-recap-name">'+sec.name+'</td><td>'+CC_fmtInt(sgr)+'</td><td>'+CC_fmtInt(spl)+'</td><td>'+CC_fmtInt(smu)+'</td><td><strong>'+CC_fmtInt(tot)+'</strong></td></tr>';
  });
  html+='</tbody><tfoot><tr class="sec-recap-total"><td>Total</td><td>'+CC_fmtInt(totGr)+'</td><td>'+CC_fmtInt(totPl)+'</td><td>'+CC_fmtInt(totMu)+'</td><td>'+CC_fmtInt(totGr+totPl+totMu)+'</td></tr></tfoot></table>';
  div.innerHTML=html;
}

// ─────────────────────────────────────────────────────────
//  STICKY HEADERS
// ─────────────────────────────────────────────────────────
function CC_initStickyHeads(){
  document.querySelectorAll('table[id^="CC_tbl_"]').forEach(function(tbl){
    var thead=tbl.querySelector('thead');
    if(!thead)return;
    var clone=document.createElement('div');
    clone.className='gp-sticky-head';
    var ct=document.createElement('table');
    ct.innerHTML='<thead>'+thead.innerHTML+'</thead>';
    clone.appendChild(ct);
    document.body.appendChild(clone);
    var obs=new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(!entry.isIntersecting){
          var rect=tbl.getBoundingClientRect();
          clone.style.display='block';
          clone.style.left=rect.left+'px';
          clone.style.width=rect.width+'px';
          clone.style.top='70px';
        } else {
          clone.style.display='none';
        }
      });
    },{threshold:0});
    obs.observe(thead);
  });
}

// ─────────────────────────────────────────────────────────
//  PANIER ODOO
// ─────────────────────────────────────────────────────────
var CC_PRODUCT_TEMPLATE_ID=307;
var CC_PRODUCT_VARIANT_ID=482;
function CC_ajouterAuPanier(){
  var metaS=CC_gid('CC_meta_surplus');
  var qty=metaS?parseInt(metaS.textContent,10):0;
  if(!qty||isNaN(qty))return;
  var btn=CC_gid('CC_btnPanier');
  if(btn){btn.disabled=true;btn.textContent='Ajout en cours\u2026';}
  var status=CC_gid('CC_panierStatus');
  fetch('/shop/cart/add',{
    method:'POST',credentials:'include',
    headers:{'Content-Type':'application/json','Accept':'application/json'},
    body:JSON.stringify({jsonrpc:'2.0',method:'call',id:1,params:{
      product_template_id:CC_PRODUCT_TEMPLATE_ID,
      product_id:CC_PRODUCT_VARIANT_ID,
      quantity:qty,add_qty:qty,
      product_custom_attribute_values:[],no_variant_attribute_values:[]
    }})
  }).then(function(r){return r.json();}).then(function(data){
    if(btn){btn.disabled=false;btn.textContent='Ajouter au panier';}
    if(data&&data.error){if(status)status.textContent='\u26a0 Erreur: '+JSON.stringify(data.error);}
    else{if(status)status.innerHTML='\u2713 '+qty+' sacs ajout\u00e9s! <a href="/shop/cart" style="color:#1a1a1a;font-weight:700">Voir le panier \u2192</a>';}
  }).catch(function(e){
    if(btn){btn.disabled=false;btn.textContent='Ajouter au panier';}
    if(status)status.textContent='\u26a0 Erreur r\u00e9seau: '+e.message;
  });
}

// ─────────────────────────────────────────────────────────
//  SAUVEGARDE / CHARGEMENT
// ─────────────────────────────────────────────────────────
function CC_saveLocal(){
  try{
    var data={
      v:1,ts:Date.now(),
      proj:{no:CC_gid('CC_projNo')?CC_gid('CC_projNo').value:'',nom:CC_gid('CC_projNom')?CC_gid('CC_projNom').value:'',cli:CC_gid('CC_projCli')?CC_gid('CC_projCli').value:'',ent:CC_gid('CC_projEnt')?CC_gid('CC_projEnt').value:'',adr:CC_gid('CC_projAdr')?CC_gid('CC_projAdr').value:'',ville:CC_gid('CC_projVille')?CC_gid('CC_projVille').value:'',prov:CC_gid('CC_projProv')?CC_gid('CC_projProv').value:'',cp:CC_gid('CC_projCP')?CC_gid('CC_projCP').value:'',notes:CC_gid('CC_projNotes')?CC_gid('CC_projNotes').value:''},
      rows:CC_rows,sections:CC_sections,buf:CC_getBuf(),unit:CC_unitSystem
    };
    localStorage.setItem(CC_SAVE_KEY,JSON.stringify(data));
    CC_updateSaveLabel();
    var st=CC_gid('CC_saveStatus');if(st){st.textContent='Sauvegard\u00e9 \u2713';setTimeout(function(){st.textContent='';},2500);}
  }catch(e){console.error('[CC] Save fail',e);}
}
function CC_loadLocal(){
  try{
    var raw=localStorage.getItem(CC_SAVE_KEY);
    if(!raw)return false;
    var data=JSON.parse(raw);
    if(!data||!data.rows)return false;
    // Projet
    var p=data.proj||{};
    ['No','Nom','Cli','Ent','Adr','Ville','Prov','CP','Notes'].forEach(function(k){
      var el=CC_gid('CC_proj'+k);
      if(el)el.value=p[k.toLowerCase()]||'';
    });
    // Sections
    if(data.sections&&data.sections.length)CC_sections=data.sections;
    // Rangées
    CC_rows=data.rows;
    // Buffer
    var buf=data.buf||5;
    ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=buf;});
    ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=buf;});
    var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=buf+'%';
    // Unités
    if(data.unit&&data.unit!==CC_unitSystem){
      var seg=CC_gid('CC_unitSeg');
      if(seg){
        var btns=seg.querySelectorAll('button');
        btns.forEach(function(b){if(b.textContent.trim().startsWith(data.unit==='imp'?'pi':'mm'))b.classList.add('active');else b.classList.remove('active');});
      }
      CC_setUnitSystem(data.unit,null);
    }
    CC_renderSectionsBar();
    CC_renderAllTables();
    CC_updateSaveLabel(data.ts);
    return true;
  }catch(e){console.error('[CC] Load fail',e);return false;}
}
function CC_updateSaveLabel(ts){
  var el=CC_gid('CC_saveLabel');if(!el)return;
  if(!ts){try{var raw=localStorage.getItem(CC_SAVE_KEY);if(raw){var d=JSON.parse(raw);ts=d.ts;}}catch(e){}}
  if(ts){var dt=new Date(ts);el.innerHTML='Derni\u00e8re sauvegarde&nbsp;: <strong>'+dt.toLocaleString('fr-CA')+'</strong>';}
  else el.textContent='Aucune sauvegarde locale';
}
function CC_hasContent(){
  return Object.keys(CC_rows).some(function(z){return (CC_rows[z]||[]).length>0;});
}
function CC_newProject(){
  if(!confirm('Effacer le projet en cours et repartir de z\u00e9ro\u00a0?'))return;
  CC_rows={grenier:[],plafonds:[],murs:[],pig:[],ouv:[]};
  CC_sections=[{id:'s1',name:'Section 1'}];
  ['CC_projNo','CC_projNom','CC_projCli','CC_projEnt','CC_projAdr','CC_projVille','CC_projProv','CC_projCP','CC_projNotes'].forEach(function(id){var el=CC_gid(id);if(el)el.value='';});
  CC_renderSectionsBar();
  CC_renderAllTables();
  CC_addRow('murs');
  CC_recalc();
}
function CC_exportJSON(){
  CC_saveLocal();
  try{
    var raw=localStorage.getItem(CC_SAVE_KEY);
    if(!raw)return;
    var blob=new Blob([raw],{type:'application/json'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='cellulose-profibcell-'+(CC_gid('CC_projNo')?CC_gid('CC_projNo').value:'projet')+'.json';
    a.click();
  }catch(e){}
}
function CC_importJSON(input){
  var file=input.files[0];if(!file)return;
  var reader=new FileReader();
  reader.onload=function(e){
    try{
      localStorage.setItem(CC_SAVE_KEY,e.target.result);
      CC_loadLocal();
      CC_recalc();
    }catch(ex){alert('Fichier JSON invalide.');}
  };
  reader.readAsText(file);
  input.value='';
}

// ─────────────────────────────────────────────────────────
//  EXPORT PDF
// ─────────────────────────────────────────────────────────
function CC_exportPDF(){
  var overlay=CC_gid('CC_exportOverlay');
  var msg=CC_gid('CC_exportMsg');
  if(overlay)overlay.classList.add('visible');
  if(msg)msg.textContent='Chargement de jsPDF\u2026';

  // Charger jsPDF si pas déjà présent
  function doExport(){
    if(msg)msg.textContent='G\u00e9n\u00e9ration du PDF\u2026';
    try{
      var jsPDF=window.jspdf?window.jspdf.jsPDF:window.jsPDF;
      var autoTable=window.jspdf&&window.jspdf.autoTable;
      var doc=new jsPDF({orientation:'portrait',unit:'mm',format:'letter'});
      var primary=[26,26,26];
      var light=[240,240,240];
      var W=doc.internal.pageSize.getWidth();
      var buf=CC_getBuf();
      var proj={
        no:CC_gid('CC_projNo')?CC_gid('CC_projNo').value:'',
        nom:CC_gid('CC_projNom')?CC_gid('CC_projNom').value:'',
        cli:CC_gid('CC_projCli')?CC_gid('CC_projCli').value:'',
        ent:CC_gid('CC_projEnt')?CC_gid('CC_projEnt').value:''
      };

      // Page de garde
      doc.setFillColor(26,26,26);doc.rect(0,0,W,48,'F');
      doc.setTextColor(255,255,255);
      doc.setFontSize(20);doc.setFont(undefined,'bold');
      doc.text('Calculateur de cellulose souffl\u00e9e',14,18);
      doc.setFontSize(11);doc.setFont(undefined,'normal');
      doc.text('PROFIB CELL \u2014 Go Passif',14,26);
      doc.setFontSize(9);
      if(proj.nom)doc.text('Projet: '+proj.nom+(proj.no?' ('+proj.no+')':''),14,34);
      if(proj.cli)doc.text('Client: '+proj.cli,14,39);
      if(proj.ent)doc.text('Entrepreneur: '+proj.ent,14,44);
      doc.setTextColor(0,0,0);

      var y=56;
      function addSection(title,rows,cols,totRow){
        if(!rows||!rows.length)return;
        doc.setFillColor.apply(doc,light);doc.rect(14,y-5,W-28,8,'F');
        doc.setFontSize(11);doc.setFont(undefined,'bold');doc.setTextColor.apply(doc,primary);
        doc.text(title,16,y);doc.setTextColor(0,0,0);y+=4;
        if(window.jspdf&&window.jspdf.autoTable){
          window.jspdf.autoTable(doc,{
            startY:y,
            head:[cols.map(function(c){return c.h;})],
            body:rows,
            foot:totRow?[totRow]:undefined,
            theme:'striped',
            headStyles:{fillColor:primary,textColor:255,fontSize:8,fontStyle:'bold'},
            footStyles:{fillColor:light,textColor:[26,26,26],fontStyle:'bold',fontSize:9},
            bodyStyles:{fontSize:9},
            styles:{cellPadding:2},
            margin:{left:14,right:14}
          });
          y=doc.lastAutoTable.finalY+8;
        } else {y+=8;}
        if(y>220){doc.addPage();y=20;}
      }

      // Grenier
      var gRows=CC_rows.grenier.map(function(r){
        var surf=r._surf||0,qty=CC_pf(r.qty)||1;
        return [r.label||'',qty,CC_fmt(surf,1),CC_fmtInt((r._sacs||0)*qty)];
      });
      addSection('Grenier / Entretoit',gRows,[{h:'Identification'},{h:'Qt\u00e9'},{h:'Surface (pi\u00b2)'},{h:'Sacs'}],
        ['Sous-total','','',CC_fmtInt(CC_rows.grenier.reduce(function(s,r){return s+(r._sacs||0)*(CC_pf(r.qty)||1);},0))]);

      // Plafonds
      var pRows=CC_rows.plafonds.map(function(r){
        var surf=r._surf||0,qty=CC_pf(r.qty)||1;
        return [r.label||'',qty,CC_fmt(surf,1),CC_fmt(r.ht||0,2)+' po',CC_fmtInt((r._sacs||0)*qty)];
      });
      addSection('Plafond-plancher',pRows,[{h:'Identification'},{h:'Qt\u00e9'},{h:'Surface (pi\u00b2)'},{h:'\u00c9paisseur (po)'},{h:'Sacs'}],
        ['Sous-total','','','',CC_fmtInt(CC_rows.plafonds.reduce(function(s,r){return s+(r._sacs||0)*(CC_pf(r.qty)||1);},0))]);

      // Murs
      var mRows=CC_rows.murs.map(function(r){
        var surf=r._surf||0,qty=CC_pf(r.qty)||1;
        return [r.label||'',qty,CC_fmt(surf,1),CC_fmt(CC_pf(r.ep)||5.5,2)+' po',CC_fmtInt((r._sacs||0)*qty)];
      });
      addSection('Murs',mRows,[{h:'Identification'},{h:'Qt\u00e9'},{h:'Surface (pi\u00b2)'},{h:'\u00c9paisseur (po)'},{h:'Sacs'}],
        ['Sous-total','','','',CC_fmtInt(CC_rows.murs.reduce(function(s,r){return s+(r._sacs||0)*(CC_pf(r.qty)||1);},0))]);

      // Résumé final
      if(y>200){doc.addPage();y=20;}
      doc.setFillColor(26,26,26);doc.rect(14,y-5,W-28,50,'F');
      doc.setTextColor(255,255,255);
      doc.setFontSize(13);doc.setFont(undefined,'bold');
      doc.text('R\u00e9sum\u00e9 \u2014 PROFIB CELL',16,y+4);
      doc.setFontSize(10);doc.setFont(undefined,'normal');
      var heroSacs=CC_gid('CC_heroSacs')?CC_gid('CC_heroSacs').textContent:'—';
      var heroPal=CC_gid('CC_heroPal')?CC_gid('CC_heroPal').textContent:'—';
      doc.text('Sacs avec buffer '+buf+'%: '+heroSacs,16,y+14);
      doc.text('Palettes: '+heroPal,16,y+21);
      doc.text('Grenier: '+CC_fmtInt(CC_rows.grenier.reduce(function(s,r){return s+(r._sacs||0)*(CC_pf(r.qty)||1);},0))+' sacs',16,y+29);
      doc.text('Plafonds: '+CC_fmtInt(CC_rows.plafonds.reduce(function(s,r){return s+(r._sacs||0)*(CC_pf(r.qty)||1);},0))+' sacs',16,y+36);
      doc.text('Murs + Pignons: '+CC_gid('CC_sumMurs').textContent+' sacs',16,y+43);
      doc.setTextColor(0,0,0);

      doc.save('cellulose-profibcell-'+(proj.no||'projet')+'.pdf');
    }catch(e){console.error('[CC] PDF fail',e);}
    if(overlay)overlay.classList.remove('visible');
  }

  if(!window.jspdf){
    var s=document.createElement('script');
    s.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
    s.onload=function(){
      var s2=document.createElement('script');
      s2.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js';
      s2.onload=doExport;
      document.head.appendChild(s2);
    };
    document.head.appendChild(s);
  } else { doExport(); }
}

// ─────────────────────────────────────────────────────────
//  BOOT
// ─────────────────────────────────────────────────────────
function CC_boot(){
  document.documentElement.setAttribute('data-density','compact');

  try{
    var zi=localStorage.getItem(CC_ZOOM_KEY);
    if(zi!==null){var n=parseInt(zi,10);if(!isNaN(n)&&n>=0&&n<CC_zoomLevels.length)CC_zoomIdx=n;}
  }catch(e){}
  CC_applyZoom();

  window.addEventListener('scroll',CC_onScroll,{passive:true});
  setInterval(function(){try{if(CC_hasContent())CC_saveLocal();}catch(e){}},120000);

  CC_renderSectionsBar();
  CC_setUnitSystem('imp',CC_gid('CC_unitSeg')?CC_gid('CC_unitSeg').querySelector('button.active'):null);
  CC_initStickyHeads();
  CC_updateCfgDisplays();
  CC_onZoneHeaderChange('grenier');
  CC_onZoneHeaderChange('plafonds');

  if(!CC_loadLocal()){
    CC_addRow('grenier');
    CC_addRow('plafonds');
    CC_addRow('murs');
    CC_recalc();
  }
  CC_updateSaveLabel();
}

// Lancement
CC_injectUI(CC_boot);
